def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, max(1.0, DAILY_SALARY * 0.25)))

    prev_bids = []
    danger_count = 0
    rich_count = 0
    for opp in alive:
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
            danger_count += 1
        if opp.get('budget', 0) >= 250:
            rich_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    highest_prev = max(prev_bids) if prev_bids else 0.0
    moderate_prev = [b for b in prev_bids if b <= 140]
    ref_prev = max(moderate_prev) if moderate_prev else highest_prev

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    urgency = 0
    if hp <= 2 or no_water >= 2:
        urgency = 3
    elif hp <= 4 or no_water >= 1:
        urgency = 2
    elif hp <= 6:
        urgency = 1

    if urgency >= 3:
        bid = max(0.92 * DAILY_SALARY, ref_prev + 4.0)
        if rich_count >= 2 and scarcity >= 1:
            bid = max(bid, 96.0)
    elif urgency == 2:
        bid = max(0.62 * DAILY_SALARY, min(ref_prev + 2.5, 82.0))
        if scarcity >= 1:
            bid += 6.0
    elif urgency == 1:
        bid = 0.42 * DAILY_SALARY
        if scarcity >= 2:
            bid = max(bid, 38.0)
        elif scarcity == 1:
            bid = max(bid, 33.0)
        if ref_prev > 0 and ref_prev < 80:
            bid = max(bid, ref_prev + 1.5)
    else:
        bid = 0.24 * DAILY_SALARY
        if scarcity >= 2:
            bid = 24.0
        elif scarcity == 1:
            bid = 20.0
        if danger_count >= 2:
            bid *= 0.9

    if highest_prev >= 160 and urgency <= 1:
        bid = min(bid, 30.0)
    if highest_prev >= 200 and urgency == 0:
        bid = min(bid, 22.0)

    if budget < DAILY_SALARY:
        bid = min(bid, max(8.0, budget * 0.72))
    else:
        bid = min(bid, budget * 0.85)

    if hp <= 2 and budget > 0:
        bid = max(bid, min(budget, 90.0))

    bid = max(1.0, min(float(budget), float(bid)))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace only (immediate reaction)
    prev_bids = []
    for o in alive_opps:
        pt = o.get('previous_trace', {})
        b = pt.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how many rounds of water we can afford if we win today
    # (not perfect, but helps avoid bankruptcy)
    # If supply is enough to cover our requirement, winning is valuable.
    supply_covers = supply >= WATER_REQ

    # Risk-based bid scaling
    # If we are already in danger of running out, bid more.
    danger = (hp <= 2.5) or (no_water_days >= 2)

    # If opponents were aggressive yesterday (high bids), slightly increase to compete.
    aggressive = highest_prev_bid >= (DAILY_SALARY * 0.8)

    # Baseline target: moderate spend to secure water when supply covers requirement.
    if supply_covers:
        base = DAILY_SALARY * 0.45
    else:
        base = DAILY_SALARY * 0.25

    if danger:
        bid = base + DAILY_SALARY * 0.35
    elif aggressive:
        bid = base + DAILY_SALARY * 0.15
    else:
        bid = base

    # Keep bid within budget and avoid reckless spending
    # Also cap by a fraction of budget to reduce variance.
    max_reasonable = budget * 0.35 if budget > 0 else 0.0
    bid = min(bid, max_reasonable if max_reasonable > 0 else bid)

    # If budget is very low, bid whatever we can to prevent death.
    if budget <= DAILY_SALARY * 0.2:
        bid = budget * 0.9

    # Ensure non-negative
    if bid < 0:
        bid = 0.0

    return float(bid)

